void tg3_read_vpd_info(struct tg3 *tp)
{
    u8 vpd_data[256];
    int i, j, len;
    u32 val;
    const char *fwver = "0.0.0.0";
    const char *partno = "BCMxxxx-xx";
    const char *mfgid = "0000";
    const char *vendor = "0000";

    if (tg3_read_vpd(tp, vpd_data, sizeof(vpd_data)) < 0)
        goto use_defaults;

    for (i = 0; i < sizeof(vpd_data); i++) {
        if (vpd_data[i] == 'M' && i + 4 < sizeof(vpd_data)) {
            if (memcmp(vpd_data + i, "MFGID", 5) == 0) {
                mfgid = (const char *)vpd_data + i + 5;
                while (i < sizeof(vpd_data) && vpd_data[i] != '\n')
                    i++;
                break;
            }
        } else if (vpd_data[i] == 'V' && i + 5 < sizeof(vpd_data)) {
            if (memcmp(vpd_data + i, "VENDOR", 6) == 0) {
                vendor = (const char *)vpd_data + i + 6;
                while (i < sizeof(vpd_data) && vpd_data[i] != '\n')
                    i++;
                break;
            }
        } else if (vpd_data[i] == 'F' && i + 5 < sizeof(vpd_data)) {
            if (memcmp(vpd_data + i, "FWVER", 5) == 0) {
                fwver = (const char *)vpd_data + i + 5;
                while (i < sizeof(vpd_data) && vpd_data[i] != '\n')
                    i++;
                break;
            }
        } else if (vpd_data[i] == 'P' && i + 6 < sizeof(vpd_data)) {
            if (memcmp(vpd_data + i, "PARTNO", 6) == 0) {
                partno = (const char *)vpd_data + i + 6;
                while (i < sizeof(vpd_data) && vpd_data[i] != '\n')
                    i++;
                break;
            }
        }
    }

    len = strlen(fwver);
    if (len > TG3_FW_VERSION_LEN - 1)
        len = TG3_FW_VERSION_LEN - 1;
    strncpy(tp->fw_version, fwver, len);
    tp->fw_version[len] = '\0';

    len = strlen(partno);
    if (len > TG3_BOARD_PARTNO_LEN - 1)
        len = TG3_BOARD_PARTNO_LEN - 1;
    strncpy(tp->board_partno, partno, len);
    tp->board_partno[len] = '\0';

    return;

use_defaults:
    val = tg3_read_asic_rev(tp);
    switch (val) {
    case ASIC_REV_5700:
        snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCM5700-B0");
        break;
    case ASIC_REV_5701:
        snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCM5701-B0");
        break;
    case ASIC_REV_5703:
        snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCM5703-B0");
        break;
    default:
        snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCMXXXX-XX");
        break;
    }

    snprintf(tp->fw_version, TG3_FW_VERSION_LEN, "0.0.0.0");
}

void tg3_read_vpd(struct tg3 *tp) {
    char vpd_data[256];
    char *fw_ver, *part_num;
    int i;

    if (tg3_read_vpd_block(tp, vpd_data, sizeof(vpd_data)) == 0) {
        fw_ver = strstr(vpd_data, "fw-ver=");
        part_num = strstr(vpd_data, "part-number=");

        if (fw_ver != NULL && part_num != NULL) {
            fw_ver += strlen("fw-ver=");
            part_num += strlen("part-number=");

            for (i = 0; i < 32 && fw_ver[i] && fw_ver[i] != '\n'; i++)
                tp->fw_ver[i] = fw_ver[i];
            tp->fw_ver[i] = '\0';

            for (i = 0; i < 32 && part_num[i] && part_num[i] != '\n'; i++)
                tp->board_part_number[i] = part_num[i];
            tp->board_part_number[i] = '\0';
        } else {
            /* Fallback to default values based on ASIC and device type */
            snprintf(tp->fw_ver, 32, "default-fw");
            snprintf(tp->board_part_number, 32, "default-part");
        }
    } else {
        /* Fallback to default values if VPD is not available */
        snprintf(tp->fw_ver, 32, "default-fw");
        snprintf(tp->board_part_number, 32, "default-part");
    }
}

void tg3_get_vpd_info(struct tg3 *tp) {
    u8 vpd_data[256];
    int i, j, len;
    int found_manufacturer_id = 0;
    int found_vendor_info = 0;
    char *fw_version = NULL;
    char *board_partnum = NULL;

    len = tg3_read_vpd(tp, vpd_data, sizeof(vpd_data));
    if (len > 0) {
        for (i = 0, j = 0; i < len && j < 256; i++) {
            if (vpd_data[i] == 'M' && i + 11 < len &&
                vpd_data[i+1] == 'a' && vpd_data[i+2] == 'n' &&
                vpd_data[i+3] == 'u' && vpd_data[i+4] == 'f' &&
                vpd_data[i+5] == 'a' && vpd_data[i+6] == 'c' &&
                vpd_data[i+7] == 't' && vpd_data[i+8] == 'u' &&
                vpd_data[i+9] == 'r' && vpd_data[i+10] == 'e' &&
                vpd_data[i+11] == 'r' && vpd_data[i+12] == ' ') {
                i += 12;
                found_manufacturer_id = 1;
            } else if (vpd_data[i] == 'V' && i + 6 < len &&
                       vpd_data[i+1] == 'e' && vpd_data[i+2] == 'n' &&
                       vpd_data[i+3] == 'd' && vpd_data[i+4] == 'o' &&
                       vpd_data[i+5] == 'r' && vpd_data[i+6] == ' ') {
                i += 5;
                found_vendor_info = 1;
            }

            if (found_manufacturer_id && vpd_data[i] == 'F') {
                if (i + 9 < len && vpd_data[i+1] == 'W' &&
                    vpd_data[i+2] == ' ' && vpd_data[i+3] == 'v' &&
                    vpd_data[i+4] == 'e' && vpd_data[i+5] == 'r' &&
                    vpd_data[i+6] == 's' && vpd_data[i+7] == 'i' &&
                    vpd_data[i+8] == 'o' && vpd_data[i+9] == 'n') {
                    i += 9;
                    fw_version = &vpd_data[i + 1];
                }
            }

            if (found_vendor_info && vpd_data[i] == 'P') {
                if (i + 10 < len && vpd_data[i+1] == 'a' &&
                    vpd_data[i+2] == 'r' && vpd_data[i+3] == 't' &&
                    vpd_data[i+4] == ' ' && vpd_data[i+5] == 'N' &&
                    vpd_data[i+6] == 'u' && vpd_data[i+7] == 'm' &&
                    vpd_data[i+8] == 'b' && vpd_data[i+9] == 'e' &&
                    vpd_data[i+10] == 'r') {
                    i += 10;
                    board_partnum = &vpd_data[i + 1];
                }
            }
        }

        if (fw_version != NULL && board_partnum != NULL) {
            snprintf(tp->fw_version, sizeof(tp->fw_version), "%s", fw_version);
            snprintf(tp->board_partnum, sizeof(tp->board_partnum), "%s", board_partnum);
            return;
        }
    }

    switch (tp->pci_chip_rev_id & TG3_REV_MASK) {
    case CHIPREV_ID_5700_A0:
    case CHIPREV_ID_5700_A1:
    case CHIPREV_ID_5700_A2:
    case CHIPREV_ID_5700_A3:
    case CHIPREV_ID_5700_A4:
    case CHIPREV_ID_5700_A5:
        snprintf(tp->fw_version, sizeof(tp->fw_version), "5700-A5");
        snprintf(tp->board_partnum, sizeof(tp->board_partnum), "BCM5700");
        break;
    case CHIPREV_ID_5701_A0:
    case CHIPREV_ID_5701_A1:
    case CHIPREV_ID_5701_A2:
    case CHIPREV_ID_5701_B0:
    case CHIPREV_ID_5701_B1:
    case CHIPREV_ID_5701_B2:
    case CHIPREV_ID_5701_C0:
    case CHIPREV_ID_5701_C1:
    case CHIPREV_ID_5701_C2:
        snprintf(tp->fw_version, sizeof(tp->fw_version), "5701-C2");
        snprintf(tp->board_partnum, sizeof(tp->board_partnum), "BCM5701");
        break;
    default:
        if (tg3_flag(tp, IS_SSB)) {
            snprintf(tp->fw_version, sizeof(tp->fw_version), "SSB-1.0");
            snprintf(tp->board_partnum, sizeof(tp->board_partnum), "BCM5705");
        } else {
            snprintf(tp->fw_version, sizeof(tp->fw_version), "5705-B0");
            snprintf(tp->board_partnum, sizeof(tp->board_partnum), "BCM5705");
        }
        break;
    }
}

void tg3_read_vpd_info(struct tg3 *tp) {
    u8 *vpd_data = NULL;
    int vpd_size = 0;
    int i = 0, j = 0;

    vpd_size = pci_read_vpd(tp->pdev, 0, 0, NULL);
    if (vpd_size > 0) {
        vpd_data = kmalloc(vpd_size, GFP_KERNEL);
        if (!vpd_data)
            return;

        pci_read_vpd(tp->pdev, 0, vpd_size, vpd_data);

        for (i = 0; i < vpd_size; i++) {
            if (vpd_data[i] == 'F' && i + 13 < vpd_size &&
                memcmp(&vpd_data[i], "FIRMWARE VERSION ", 17) == 0) {
                for (j = 0; j < 16 && i + 17 + j < vpd_size; j++) {
                    if (vpd_data[i + 17 + j] == ' ')
                        break;
                    tp->fw_ver[j] = vpd_data[i + 17 + j];
                }
                tp->fw_ver[j] = '\0';
            }

            if (vpd_data[i] == 'P' && i + 11 < vpd_size &&
                memcmp(&vpd_data[i], "PART NUMBER ", 12) == 0) {
                for (j = 0; j < 32 && i + 12 + j < vpd_size; j++) {
                    if (vpd_data[i + 12 + j] == ' ')
                        break;
                    tp->part_number[j] = vpd_data[i + 12 + j];
                }
                tp->part_number[j] = '\0';
            }
        }

        kfree(vpd_data);
    }

    if (tp->fw_ver[0] == '\0') {
        switch (tp->pci_chip_rev_id & TG3_REV_MASK) {
            case CHIPREV_5700_5701:
                strcpy(tp->fw_ver, "5700");
                break;
            case CHIPREV_5750:
                strcpy(tp->fw_ver, "5750");
                break;
            default:
                strcpy(tp->fw_ver, "unknown");
                break;
        }
    }

    if (tp->part_number[0] == '\0') {
        switch (tp->pci_chip_rev_id & TG3_REV_MASK) {
            case CHIPREV_5700_5701:
                strcpy(tp->part_number, "BCM5700");
                break;
            case CHIPREV_5750:
                strcpy(tp->part_number, "BCM5750");
                break;
            default:
                strcpy(tp->part_number, "unknown");
                break;
        }
    }
}

void tg3_read_vpd_info(struct tg3 *tp)
{
    u8 vpd_data[256];
    u8 *vpd;
    int i, j, len;
    int found_manufacturer = 0, found_vendor = 0;
    int fw_start = -1, part_start = -1;

    /* Attempt to read VPD data block */
    if (tp->vpd_size > 0 && tp->vpd_data) {
        vpd = tp->vpd_data;

        for (i = 0; i < tp->vpd_size; i++) {
            if (vpd[i] == 'M' && i + 13 < tp->vpd_size &&
                vpd[i + 1] == 'A' && vpd[i + 2] == 'N' &&
                vpd[i + 3] == 'U' && vpd[i + 4] == 'F' &&
                vpd[i + 5] == 'A' && vpd[i + 6] == 'C' &&
                vpd[i + 7] == 'T' && vpd[i + 8] == 'U' &&
                vpd[i + 9] == 'R' && vpd[i + 10] == 'E' &&
                vpd[i + 11] == 'R' && vpd[i + 12] == ' ' &&
                vpd[i + 13] == ':') {
                found_manufacturer = 1;
                fw_start = i + 14;
                break;
            }
        }

        if (fw_start == -1) {
            for (i = 0; i < tp->vpd_size; i++) {
                if (vpd[i] == 'V' && i + 6 < tp->vpd_size &&
                    vpd[i + 1] == 'E' && vpd[i + 2] == 'N' &&
                    vpd[i + 3] == 'D' && vpd[i + 4] == 'O' &&
                    vpd[i + 5] == 'R' && vpd[i + 6] == ' ') {
                    found_vendor = 1;
                    part_start = i + 7;
                    break;
                }
            }
        }

        if (found_manufacturer) {
            for (i = fw_start; i < tp->vpd_size; i++) {
                if (vpd[i] == ' ' || vpd[i] == '\0' || vpd[i] == '\r' || vpd[i] == '\n') {
                    break;
                }
            }

            len = i - fw_start;
            if (len > TG3_FIRMWARE_VERSION_SIZE - 1)
                len = TG3_FIRMWARE_VERSION_SIZE - 1;

            for (j = 0; j < len; j++) {
                tp->fw_version[j] = vpd[fw_start + j];
            }
            tp->fw_version[j] = '\0';
        }

        if (found_vendor) {
            for (i = part_start; i < tp->vpd_size; i++) {
                if (vpd[i] == ' ' || vpd[i] == '\0' || vpd[i] == '\r' || vpd[i] == '\n') {
                    break;
                }
            }

            len = i - part_start;
            if (len > TG3_BOARD_PARTNUM_SIZE - 1)
                len = TG3_BOARD_PARTNUM_SIZE - 1;

            for (j = 0; j < len; j++) {
                tp->board_part_number[j] = vpd[part_start + j];
            }
            tp->board_part_number[j] = '\0';
        }

        if (!found_manufacturer || !found_vendor) {
            if (tp->pci_chip_rev_id == CHIPREV_ID_5705_A0 ||
                tp->pci_chip_rev_id == CHIPREV_ID_5705_A1 ||
                tp->pci_chip_rev_id == CHIPREV_ID_5705_B0 ||
                tp->pci_chip_rev_id == CHIPREV_ID_5705_C0 ||
                tp->pci_chip_rev_id == CHIPREV_ID_5705_D0) {
                snprintf(tp->board_part_number, TG3_BOARD_PARTNUM_SIZE, "BCM5705");
            } else if (tp->pci_chip_rev_id == CHIPREV_ID_5705_A0 ||
                       tp->pci_chip_rev_id == CHIPREV_ID_5705_A1 ||
                       tp->pci_chip_rev_id == CHIPREV_ID_5705_B0 ||
                       tp->pci_chip_rev_id == CHIPREV_ID_5705_C0 ||
                       tp->pci_chip_rev_id == CHIPREV_ID_5705_D0) {
                snprintf(tp->board_part_number, TG3_BOARD_PARTNUM_SIZE, "BCM5706");
            } else {
                snprintf(tp->board_part_number, TG3_BOARD_PARTNUM_SIZE, "Unknown Part Number");
            }
        }
    } else {
        if (tp->pci_chip_rev_id == CHIPREV_ID_5705_A0 ||
            tp->pci_chip_rev_id == CHIPREV_ID_5705_A1 ||
            tp->pci_chip_rev_id == CHIPREV_ID_5705_B0 ||
            tp->pci_chip_rev_id == CHIPREV_ID_5705_C0 ||
            tp->pci_chip_rev_id == CHIPREV_ID_5705_D0) {
            snprintf(tp->board_part_number, TG3_BOARD_PARTNUM_SIZE, "BCM5705");
        } else if (tp->pci_chip_rev_id == CHIPREV_ID_5705_A0 ||
                   tp->pci_chip_rev_id == CHIPREV_ID_5705_A1 ||
                   tp->pci_chip_rev_id == CHIPREV_ID_5705_B0 ||
                   tp->pci_chip_rev_id == CHIPREV_ID_5705_C0 ||
                   tp->pci_chip_rev_id == CHIPREV_ID_5705_D0) {
            snprintf(tp->board_part_number, TG3_BOARD_PARTNUM_SIZE, "BCM5706");
        } else {
            snprintf(tp->board_part_number, TG3_BOARD_PARTNUM_SIZE, "Unknown Part Number");
        }
    }
}
